use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut total = 0;
    if let Some(input_array) = input.as_array() {
        for item in input_array {
            if let Some(item_array) = item.as_array() {
                for sub_item in item_array {
                    if let Some(sub_item_array) = sub_item.as_array() {
                        let unit_price_cents = sub_item_array[0].to_i64().unwrap();
                        let quantity = sub_item_array[1].to_i64().unwrap();
                        total += unit_price_cents * quantity;
                    }
                }
            }
        }
    }
    Value::I64(total)
}
```

This function first checks if the input is an array. If it is, it iterates over each item in the array. If each item is an array, it again iterates over each item in the sub-array. It then extracts the unit price and quantity from each sub-array and multiplies them together to get the total. The total is then returned as a `Value::I64`.
